 internal Offline70ProgressionStateFG MapVisit(string path,int map,string receipt,int dungeon,byte difficulty,bool gsdAlive,string questInstance){return Change(path,delegate(Offline70ProgressionStateFG s){if(!Receipt(s,receipt))return;foreach(Offline70QuestActiveFG a in s.Active){Offline70QuestDefinitionFG q=catalog.Get(a.Id);if(q.Type!="[clear map]")continue;if(q.Id==4307||q.Id==4308||q.Id==4312){int targetMap=q.Id==4307?1619:q.Id==4308?1820:2408,targetDungeon=q.Id==4307?11:q.Id==4308?12:15;int minimum=q.Id==4312?2:3;if(map==targetMap&&dungeon==targetDungeon&&difficulty>=minimum&&gsdAlive&&a.Instance==questInstance){a.Progress[0]=1;if(q.Id==4312)Receipt(s,"survivor-4312-"+(a.Instance??"legacy"));}}else if(Array.IndexOf(q.Condition,map)>=0)a.Progress[0]=1;}});}
