 internal Offline70ProgressionStateFG AwardExperience(string path,uint amount,string receipt){return Change(path,delegate(Offline70ProgressionStateFG s){if(Receipt(s,receipt))s.Experience=Offline70ProgressionFG.AddExperience(s.Experience,amount);});}
 internal Offline70ProgressionStateFG Complete(string path,ushort id,int npc,ushort selectionIndex,string receipt){Offline70QuestDefinitionFG q=catalog.Get(id);return Change(path,delegate(Offline70ProgressionStateFG s){if(s.Receipts.Contains(receipt))return;Offline70QuestActiveFG a=s.Find(id);if(a==null||!catalog.ActiveVisible(q,s)||Remaining(q,a,s)!=0)throw new InvalidDataException("Quest not ready "+id);int completeNpc=q.CompleteNpc>=0?q.CompleteNpc:q.Npc;if(npc!=completeNpc)throw new InvalidDataException("Quest completion NPC");if(q.Selection.Length==0&&selectionIndex!=ushort.MaxValue||q.Selection.Length>0&&selectionIndex>=q.Selection.Length/2)throw new InvalidDataException("Quest chosen reward");
  int[] fixedRewards=Offline70QuestCatalogFG.ResolvedRewards(q,s);Offline70QuestBasicRewardFG reward=Offline70QuestRewardsFG.Calculate(q,Offline70ProgressionFG.Level(s.Experience),fixedRewards);Offline70QuestOutboxFG plan=new Offline70QuestOutboxFG{Receipt=receipt,QuestId=id,GoldCredit=reward.Gold,ExperienceCredit=Offline70TestRatesFG114.Experience(reward.Experience)};foreach(Offline70QuestStartOutboxFG start in s.StartOutbox)if(start.QuestId==id&&start.Instance==a.Instance&&!start.Delivered)throw new InvalidDataException("Quest start delivery pending");foreach(KeyValuePair<int,uint> requirement in catalog.CompletionRequirements(q)){int item=requirement.Key;uint count=requirement.Value;if(item==0){s.Gold-=count;plan.GoldDebit=checked(plan.GoldDebit+count);}else{if(s.Count(item)<count)throw new InvalidDataException("Quest provided item missing");s.SetCount(item,s.Count(item)-count);plan.Debits.Add(new Offline70ItemCountFG{Id=item,Quantity=count});}}s.Gold=checked(s.Gold+reward.Gold);if(q.TitleRewardFG157){Offline70TitleBookFG157.CheckProfile(q);plan.TitleRewardFG157=Offline70TitleBookFG157.Reward(q.Id);}else for(int i=0;i<fixedRewards.Length;i+=2)if(fixedRewards[i]!=0){Reward(s,fixedRewards[i],(uint)fixedRewards[i+1]);PlanCredit(plan,fixedRewards[i],(uint)fixedRewards[i+1]);}if(q.Selection.Length>0){if(q.Selection[selectionIndex*2]==0)throw new InvalidDataException("Selected nominal gold reward is not supported");Reward(s,q.Selection[selectionIndex*2],(uint)q.Selection[selectionIndex*2+1]);PlanCredit(plan,q.Selection[selectionIndex*2],(uint)q.Selection[selectionIndex*2+1]);}if(q.RewardGrowType>0){if(q.ChangeStage()!=1||s.Job!=0||s.GrowType!=0||q.RewardGrowType>4)throw new InvalidDataException("First promotion precondition");plan.GrowTypeCredit=q.RewardGrowType;s.GrowType=q.RewardGrowType;}else if(q.RewardSecondGrow>0){if(q.ChangeStage()!=2||s.Job!=0||q.RewardSecondGrow!=1||Offline70RewardTypesFG183.FirstGrow(s.GrowType)!=q.GrowType||Offline70RewardTypesFG183.SecondGrow(s.GrowType)!=0)throw new InvalidDataException("Awakening precondition");byte awakened=Offline70RewardTypesFG183.EncodeGrow(Offline70RewardTypesFG183.FirstGrow(s.GrowType),q.RewardSecondGrow);plan.GrowTypeCredit=awakened;s.GrowType=awakened;}else if(q.RewardExpertJob>0){if(s.ExpertJobTypeFG183!=0&&s.ExpertJobTypeFG183!=q.RewardExpertJob)throw new InvalidDataException("Expert job conflict");plan.ExpertJobCreditFG183=q.RewardExpertJob;s.ExpertJobTypeFG183=q.RewardExpertJob;}s.Active.Remove(a);if(!s.Completed.Contains(id))s.Completed.Add(id);if(!Receipt(s,receipt))throw new InvalidDataException("Completion receipt");s.Outbox.Add(plan);});}
 static void PlanCredit(Offline70QuestOutboxFG plan,int id,uint quantity){if(id==0)plan.GoldCredit=checked(plan.GoldCredit+quantity);else plan.Credits.Add(new Offline70ItemCountFG{Id=id,Quantity=quantity});}
 internal static Offline70ProgressionStateFG MarkDelivered(string path,string receipt){return Change(path,delegate(Offline70ProgressionStateFG s){foreach(Offline70QuestOutboxFG plan in s.Outbox)if(plan.Receipt==receipt){plan.Delivered=true;return;}throw new InvalidDataException("No committed quest outbox receipt");});}
 static void Reward(Offline70ProgressionStateFG s,int id,uint quantity){if(id==0)s.Gold=checked(s.Gold+quantity);else s.SetCount(id,checked(s.Count(id)+quantity));}
